DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_1','Argentina - The Boy Who Touched Paradise[NEWLINE]Great Person culture, national expectations and recovery[NEWLINE]Culture; Science or Diplomacy supported by the Journey[NEWLINE][NEWLINE]Build a functioning cultural and Great Person economy while managing Dreams and national expectations. El Diez is support for that economy; the Journey''s final fulfillment needs genuine achievements and its own eligibility.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_2','Develop food and Culture, protect El Diez, and place his hosting-city benefits where Great Person generation is most useful. Establish normal defenses rather than assuming a returning civilian hero can protect a city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_3','Use El Potreros, actual Great Person births, feasible Wonders and diplomatic milestones to earn Dreams. Balance spending with the next Journey requirements. Read the current act and pressure state before delaying a meaningful achievement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_4','Complete the required national recovery and qualifying achievements, then prepare The Last Dance when its technology, Era and Journey gates are met. Fulfillment improves the cultural plan but does not replace normal victory requirements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_5','- The starting ability supports Great Person generation before the final act.[NEWLINE]- El Diez can concentrate inspiration in a selected owned city.[NEWLINE]- Several peaceful achievements support Dreams and pressure relief.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_6','- A civilian hero needs safe access and can be unavailable during recovery.[NEWLINE]- Journey progress has eligibility and pressure conditions, not just a currency total.[NEWLINE]- Purchased or administrative Great Person creation does not count as a genuine generated birth for Dreams.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_7','- Pressure the productive cultural cities and force investment away from Great Person plans.[NEWLINE]- Contest realistic Wonder and alliance opportunities rather than gifting easy milestones.[NEWLINE]- Threaten the hero''s route while recognizing that his loss schedules recovery rather than permanent elimination.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_8','- Confusing this Journey with the separate Eternal Number Ten''s Legacy career.[NEWLINE]- Assuming a purchased Great Person earns Dreams as a generated birth.[NEWLINE]- Treating El Diez''s voluntary deletion as a way to farm recovery rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Unrung Bell: A peaceful Great Person and cultural programme can make good use of the time Sable also wants for Quietude.[NEWLINE][NEWLINE]Substitute Classroom: Persistent cultural development can exploit gaps between temporary classroom bonuses, provided the defensive windows are respected.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Viltrum: City-loss pressure and a collapsing protected economy make the Journey''s achievement plan much harder.[NEWLINE][NEWLINE]The Filthy Realm: Persistent city disruption can damage the cultural base and delay the milestones needed to manage expectations.');
