INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_BACKGROUND','Build a functioning cultural and Great Person economy while managing Dreams and national expectations. El Diez is support for that economy; the Journey''s final fulfillment needs genuine achievements and its own eligibility.');
