INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_STRATEGY','Build a functioning cultural and Great Person economy while managing Dreams and national expectations. El Diez is support for that economy; the Journey''s final fulfillment needs genuine achievements and its own eligibility.[NEWLINE][NEWLINE]Develop food and Culture, protect El Diez, and place his hosting-city benefits where Great Person generation is most useful. Establish normal defenses rather than assuming a returning civilian hero can protect a city.[NEWLINE][NEWLINE]Use El Potreros, actual Great Person births, feasible Wonders and diplomatic milestones to earn Dreams. Balance spending with the next Journey requirements. Read the current act and pressure state before delaying a meaningful achievement.[NEWLINE][NEWLINE]Complete the required national recovery and qualifying achievements, then prepare The Last Dance when its technology, Era and Journey gates are met. Fulfillment improves the cultural plan but does not replace normal victory requirements.');
