INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_LEADER_TEXT_2','Develop food and Culture, protect El Diez, and place his hosting-city benefits where Great Person generation is most useful. Establish normal defenses rather than assuming a returning civilian hero can protect a city.[NEWLINE][NEWLINE]Use El Potreros, actual Great Person births, feasible Wonders and diplomatic milestones to earn Dreams. Balance spending with the next Journey requirements. Read the current act and pressure state before delaying a meaningful achievement.[NEWLINE][NEWLINE]Complete the required national recovery and qualifying achievements, then prepare The Last Dance when its technology, Era and Journey gates are met. Fulfillment improves the cultural plan but does not replace normal victory requirements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEBOYWHOTOUCHEDPARADISE_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Unrung Bell: A peaceful Great Person and cultural programme can make good use of the time Sable also wants for Quietude.[NEWLINE][NEWLINE]Substitute Classroom: Persistent cultural development can exploit gaps between temporary classroom bonuses, provided the defensive windows are respected.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Viltrum: City-loss pressure and a collapsing protected economy make the Journey''s achievement plan much harder.[NEWLINE][NEWLINE]The Filthy Realm: Persistent city disruption can damage the cultural base and delay the milestones needed to manage expectations.');
